import 'dart:async';import 'dart:math';import 'package:flutter/foundation.dart';class RoutingMetrics {  final String nodeId;  final double latencyMs;  final double batteryLevel;  final double reliabilityScore;  final int hopCount;  final DateTime timestamp;  RoutingMetrics({    required this.nodeId,    required this.latencyMs,    required this.batteryLevel,    required this.reliabilityScore,    required this.hopCount,    required this.timestamp,  });  double get cost => calculateCost(0.35, 0.25, 0.25, 0.15);  double calculateCost(double latencyWeight, double batteryWeight,      double reliabilityWeight, double hopWeight) {    final normalizedLatency = (latencyMs / 2000).clamp(0.0, 1.0);    final batteryPenalty = 1.0 - batteryLevel;    final reliabilityPenalty = 1.0 - reliabilityScore;    return (latencyWeight * normalizedLatency) +        (batteryWeight * batteryPenalty) +        (reliabilityWeight * reliabilityPenalty) +        (hopWeight * hopCount / 10);  }  Map<String, dynamic> toJson() => {        'nodeId': nodeId,        'latencyMs': latencyMs,        'batteryLevel': batteryLevel,        'reliabilityScore': reliabilityScore,        'hopCount': hopCount,        'timestamp': timestamp.toIso8601String(),        'cost': cost,      };}class RoutingPath {  final List<String> nodeIds;  final double totalCost;  final double qualityScore;  final int estimatedLatencyMs;  final int availableBandwidthKbps;  final DateTime calculatedAt;  RoutingPath({    required this.nodeIds,    required this.totalCost,    required this.qualityScore,    required this.estimatedLatencyMs,    required this.availableBandwidthKbps,    required this.calculatedAt,  });  int get hopCount => nodeIds.length - 1;  String get pathString => nodeIds.join(' -> ');  Map<String, dynamic> toJson() => {        'nodeIds': nodeIds,        'totalCost': totalCost,        'qualityScore': qualityScore,        'estimatedLatencyMs': estimatedLatencyMs,        'availableBandwidthKbps': availableBandwidthKbps,        'hopCount': hopCount,        'pathString': pathString,        'calculatedAt': calculatedAt.toIso8601String(),      };}class AdaptiveRoutingEngine {  final Map<String, RoutingMetrics> _nodeMetrics = {};  final Map<String, Map<String, double>> _linkCosts = {};  final Random _random = Random.secure();  static const double _latencyWeight = 0.35;  static const double _batteryWeight = 0.25;  static const double _reliabilityWeight = 0.25;  static const double _hopWeight = 0.15;  static const int _maxHops = 10;  final _routeUpdateController = StreamController<RoutingPath>.broadcast();  Stream<RoutingPath> get routeUpdates => _routeUpdateController.stream;  final _metricsController = StreamController<Map<String, dynamic>>.broadcast();  Stream<Map<String, dynamic>> get metricsStream => _metricsController.stream;  void updateNodeMetrics(RoutingMetrics metrics) {    _nodeMetrics[metrics.nodeId] = metrics;    _emitMetrics();  }  void updateLinkCost(String sourceId, String targetId, double cost) {    _linkCosts[sourceId] ??= {};    _linkCosts[sourceId]![targetId] = cost;  }  RoutingPath? findOptimalPath(String sourceId, String destinationId) {    if (!_nodeMetrics.containsKey(sourceId) ||        !_nodeMetrics.containsKey(destinationId)) {      return null;    }    if (sourceId == destinationId) {      return RoutingPath(        nodeIds: [sourceId],        totalCost: 0,        qualityScore: 100,        estimatedLatencyMs: 0,        availableBandwidthKbps: 1000,        calculatedAt: DateTime.now(),      );    }    final paths = _dijkstra(sourceId, destinationId);    if (paths.isEmpty) return null;    paths.sort((a, b) => a.totalCost.compareTo(b.totalCost));    final bestPath = paths.first;    _routeUpdateController.add(bestPath);    return bestPath;  }  List<RoutingPath> _dijkstra(String sourceId, String destinationId) {    final distances = <String, double>{};    final previous = <String, String?>{};    final visited = <String>{};    final paths = <RoutingPath>[];    for (final nodeId in _nodeMetrics.keys) {      distances[nodeId] = double.infinity;      previous[nodeId] = null;    }    distances[sourceId] = 0;    while (visited.length < _nodeMetrics.length) {      String? minNode;      double minDist = double.infinity;      for (final entry in distances.entries) {        if (!visited.contains(entry.key) && entry.value < minDist) {          minDist = entry.value;          minNode = entry.key;        }      }      if (minNode == null) break;      visited.add(minNode);      if (minNode == destinationId) {        final path =            _reconstructPath(sourceId, destinationId, previous, distances);        if (path != null) paths.add(path);        break;      }      for (final targetId in _nodeMetrics.keys) {        if (visited.contains(targetId)) continue;        final linkCost = _linkCosts[minNode]?[targetId] ?? 1.0;        final nodeCost = _nodeMetrics[targetId]?.cost ?? 1.0;        final newDist = distances[minNode]! + (linkCost * 0.3 + nodeCost * 0.7);        if (newDist < distances[targetId]!) {          distances[targetId] = newDist;          previous[targetId] = minNode;        }      }    }    return paths;  }  RoutingPath? _reconstructPath(String sourceId, String destinationId,      Map<String, String?> previous, Map<String, double> distances) {    final path = <String>[];    String? current = destinationId;    while (current != null) {      path.add(current);      current = previous[current];    }    if (path.isEmpty || path.last != sourceId) return null;    path.removeRange(0, path.length);    current = destinationId;    while (current != null) {      path.add(current);      current = previous[current];    }    if (path.isEmpty || path.last != sourceId) return null;    double totalLatency = 0;    int minBandwidth = 10000;    for (final nodeId in path) {      final metrics = _nodeMetrics[nodeId];      if (metrics != null) {        totalLatency += metrics.latencyMs;        if (metrics.reliabilityScore < minBandwidth) {          minBandwidth = (metrics.reliabilityScore * 1000).round();        }      }    }    final qualityScore = 100 - (distances[destinationId] ?? 0) * 100;    return RoutingPath(      nodeIds: path,      totalCost: distances[destinationId] ?? 0,      qualityScore: qualityScore.clamp(0, 100),      estimatedLatencyMs: totalLatency.round(),      availableBandwidthKbps: minBandwidth,      calculatedAt: DateTime.now(),    );  }  List<RoutingPath> findKDiversePaths(String sourceId, String destinationId,      {int k = 3}) {    if (!_nodeMetrics.containsKey(sourceId) ||        !_nodeMetrics.containsKey(destinationId)) {      return [];    }    final paths = _dijkstra(sourceId, destinationId);    return paths.take(k).toList();  }  RoutingPath? findBackupPath(String primaryPath, String destinationId) {    if (primaryPath.isEmpty) return null;    final primaryNodes = primaryPath.split(' -> ');    if (primaryNodes.length < 2) return null;    final sourceId = primaryNodes.first;    final candidates = _dijkstra(sourceId, destinationId);    for (final path in candidates) {      final hasOverlap = path.nodeIds          .skip(1)          .take(path.nodeIds.length - 2)          .any((node) => primaryNodes.contains(node));      if (!hasOverlap) return path;    }    return candidates.isNotEmpty ? candidates[1] : null;  }  double predictLinkFailure(      String sourceId, String targetId, int windowSeconds) {    final metrics = _nodeMetrics[targetId];    if (metrics == null) return 0.5;    final batteryPenalty = metrics.batteryLevel < 0.2 ? 0.3 : 0;    final latencyPenalty = metrics.latencyMs > 1000 ? 0.2 : 0;    final reliabilityBonus = metrics.reliabilityScore * 0.5;    return (0.5 + batteryPenalty + latencyPenalty - reliabilityBonus)        .clamp(0.0, 1.0);  }  List<String> getOptimalRelays({int limit = 5, double minBattery = 0.3}) {    final candidates = _nodeMetrics.entries        .where((e) => e.value.batteryLevel >= minBattery)        .where((e) => e.value.reliabilityScore > 0.5)        .toList();    candidates.sort((a, b) => a.value.cost.compareTo(b.value.cost));    return candidates.take(limit).map((e) => e.key).toList();  }  Map<String, dynamic> getNetworkHealth() {    if (_nodeMetrics.isEmpty) {      return {        'healthy': true,        'totalNodes': 0,        'averageCost': 0,        'averageReliability': 0,      };    }    final avgCost =        _nodeMetrics.values.map((m) => m.cost).reduce((a, b) => a + b) /            _nodeMetrics.length;    final avgReliability = _nodeMetrics.values            .map((m) => m.reliabilityScore)            .reduce((a, b) => a + b) /        _nodeMetrics.length;    final avgBattery =        _nodeMetrics.values.map((m) => m.batteryLevel).reduce((a, b) => a + b) /            _nodeMetrics.length;    return {      'healthy': avgReliability > 0.6 && avgBattery > 0.3,      'totalNodes': _nodeMetrics.length,      'averageCost': avgCost,      'averageReliability': avgReliability,      'averageBattery': avgBattery,      'weakNodes': _nodeMetrics.entries          .where((e) => e.value.cost > 0.7)          .map((e) => e.key)          .toList(),    };  }  void _emitMetrics() {    _metricsController.add({      'nodes': _nodeMetrics.length,      'health': getNetworkHealth(),      'optimalRelays': getOptimalRelays(),      'timestamp': DateTime.now().toIso8601String(),    });  }  Map<String, RoutingMetrics> getAllMetrics() => Map.unmodifiable(_nodeMetrics);  void clearMetrics() {    _nodeMetrics.clear();    _linkCosts.clear();  }  void dispose() {    _routeUpdateController.close();    _metricsController.close();  }}